/**
 * R8.2/R8.3 — persist-mode production proof wiring.
 *
 * `--persist-audit` must never persist decisions generated by the
 * filesystem-only `FilesystemProofResolver`. This module constructs the full
 * production proof graph used by persist mode.
 */
import type { PrismaClient } from '@prisma/client';
import { CompositeProofResolver } from './composite-proof-resolver.js';
import type { TrustedVerificationProofResolverV1 } from './trusted-proof-types.js';
import {
  FilesystemByteLocatorReader,
  S3ByteLocatorReader,
  CompositeByteLocatorReader,
} from './trusted-byte-locator-reader.js';
import { SdkS3ProofClient } from './s3-proof-adapters.js';
import type { ParserOutputProofSource } from './parser-output-proof-source.js';
import { DeclaredParserOutputProofSource } from './declared-parser-output-proof-source.js';
import {
  CompositeParserOutputProofSource,
  FilesystemParserOutputProofAdapter,
  LlamaParseParserOutputProofAdapter,
} from './parser-output-proof-adapters.js';
import type { BudgetVerificationRepositoryV1 } from '../persistence/verification-repository.js';
import { createPrismaBudgetVerificationRepository } from '../persistence/prisma-budget-verification.repository.js';

export class ProductionProofWiringError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ProductionProofWiringError';
  }
}

export interface ProductionProofWiringOptions {
  prisma: PrismaClient;
  approvedFilesystemPrefixes?: readonly string[];
  s3ProofClient?: SdkS3ProofClient;
  skipDatabaseProbe?: boolean;
  /** Explicit shared/persistent parser artifact root. */
  parserArtifactStoreRootDir?: string;
  llamaParseOutputBucket?: string;
  parserOutputProofSource?: ParserOutputProofSource;
}

export interface ProductionProofWiringResult {
  proofResolver: TrustedVerificationProofResolverV1;
  compositeResolver: CompositeProofResolver;
  repository: BudgetVerificationRepositoryV1;
  dispose(): Promise<void>;
}

export async function wireProductionProofBoundary(
  options: ProductionProofWiringOptions,
): Promise<ProductionProofWiringResult> {
  const { prisma } = options;

  if (!options.skipDatabaseProbe) {
    try {
      await prisma.$connect();
    } catch (error) {
      throw new ProductionProofWiringError(
        `persist mode requires a reachable database for the SourceDocument client: ${
          (error as Error).message
        }`,
      );
    }
  }

  const sourceDocumentClient = prisma;
  const parseJobClient = prisma;
  const s3ProofClient = options.s3ProofClient ?? new SdkS3ProofClient();
  const s3ByteReader = new S3ByteLocatorReader(s3ProofClient);
  const filesystemByteReader = new FilesystemByteLocatorReader(
    options.approvedFilesystemPrefixes ?? [],
  );
  const byteLocatorReader = new CompositeByteLocatorReader(filesystemByteReader, s3ByteReader);

  const configuredParserRoot =
    options.parserArtifactStoreRootDir ??
    process.env.BUDGET_VERIFICATION_PARSER_ARTIFACT_ROOT?.trim() ??
    '';

  // No implicit process-relative parser store in production. An explicitly
  // configured shared root may be used; otherwise local parser runs fail
  // closed while LlamaParse output remains provable from object storage.
  const localParserSource = configuredParserRoot
    ? new FilesystemParserOutputProofAdapter(configuredParserRoot, {
        requireDeclarationBinding: true,
      })
    : null;

  const rawParserOutputProofSource: ParserOutputProofSource =
    options.parserOutputProofSource ??
    new CompositeParserOutputProofSource({
      localSource: localParserSource,
      llamaParseSource: new LlamaParseParserOutputProofAdapter({
        parseJobClient,
        byteLocatorReader,
        outputBucket:
          options.llamaParseOutputBucket ??
          process.env.BUDGET_VERIFICATION_LLAMAPARSE_OUTPUT_BUCKET?.trim() ??
          'capiro-defense-budget-raw',
        requireDeclarationBinding: true,
      }),
    });

  // Central wrapper protects even custom/injected proof sources: independently
  // loaded output must expose the exact canonical content SHA declared by the
  // parser run before it can satisfy production proof.
  const parserOutputProofSource = new DeclaredParserOutputProofSource(
    rawParserOutputProofSource,
  );

  const proofResolver = new CompositeProofResolver({
    mode: 'production_proof',
    sourceDocumentClient,
    parseJobClient,
    s3Reader: s3ProofClient,
    byteLocatorReader,
    parserOutputProofSource,
  });
  const repository = createPrismaBudgetVerificationRepository(prisma);

  return {
    proofResolver,
    compositeResolver: proofResolver,
    repository,
    async dispose(): Promise<void> {
      if (!options.s3ProofClient) await s3ProofClient.destroy();
    },
  };
}
